import json

# Careful indexing
grid = [[0 for _ in range(11)] for _ in range(11)]
positions = {
    (2, 1): 1,
    (6, 7): 2,
    (7, 5): 6,
    (7, 10): 3
}

# 1. Originals
for (r,c),v in positions.items():
    grid[r][c] = v

# 2. Beams
inter_r, inter_c = 7, 1

for (r,c),val in positions.items():
    if val % 2 == 1:  # UP movement
        # Beam: r-val+1 to r-1 (val-1 cells)
        for beam_r in range(r - val + 1, r):
            if 0 <= beam_r < 11:
                grid[beam_r][c] = 5
    else:  # BOTH movement  
        # LEFT: c-val+1 to c-1 (val-1 cells)
        for beam_c in range(c - val + 1, c):
            if 0 <= beam_c < 11:
                grid[r][beam_c] = 5
        # RIGHT: c+1 to c+val (val cells)
        for beam_c in range(c + 1, c + val + 1):
            if 0 <= beam_c < 11:
                grid[r][beam_c] = 5

# 3. Intersection
grid[inter_r][inter_c] = 4

# 4. Diagonal
for i in range(1, 10):
    nr, nc = inter_r + i, inter_c - i
    if nr >= 11 or nc < 0: break
    grid[nr][nc] = 4

# 5. Restore originals
for (r,c),v in positions.items():
    grid[r][c] = v

print("Grid:")
for row in grid:
    print(' '.join(map(str, row)))
print(json.dumps({"action": "submit", "grid": grid}))

